import { isUndefined } from '@nestjs/common/internal';
/**
 * @publicApi
 */
export class IncomingResponseDeserializer {
    deserialize(value, options) {
        return this.isExternal(value) ? this.mapToSchema(value) : value;
    }
    isExternal(value) {
        if (!value) {
            return true;
        }
        if (!isUndefined(value.err) ||
            !isUndefined(value.response) ||
            !isUndefined(value.isDisposed)) {
            return false;
        }
        return true;
    }
    mapToSchema(value) {
        return {
            id: value && value.id,
            response: value,
            isDisposed: true,
        };
    }
}
